# -*- coding: utf-8 -*-
"""
@author: Taiyu Zhu
"""

import argparse
PHENO_CONT = False
def args_initial(argv=None):
    parser = argparse.ArgumentParser()
    # data define
    parser.add_argument('--SNP_len', type=int, default=50, help='length of SNP windows')
    parser.add_argument('--data_dir', type=str, default=None, help='directory of datasets')

    # model define
    parser.add_argument('--mn', type=str, default='DeepGP', help='model name')
    parser.add_argument('--enc_in', type=int, default=1, help='encoder input dimension')
    parser.add_argument('--cov_dim', type=int, default=8, help='covariate dimension')
    parser.add_argument('--c_out', type=int, default=1, help='output size')
    parser.add_argument('--d_model', type=int, default=64, help='dimension of model')
    parser.add_argument('--e_layers', type=int, default=1, help='num of SNP encoder layers')
    parser.add_argument('--dropout', type=float, default=0.25, help='dropout')
    parser.add_argument('--activation', type=str, default='gelu', help='activation')
    parser.add_argument('--output_attention', action='store_true', default=False, help='whether to output attention in encoder')
    parser.add_argument('--snp_embed', type=str, default='cov', help='embedding method: cov or vocab')
    parser.add_argument('--final_pool', type=str, default='concat', help="output head: SNP mode 'last' or 'atten' ('concat' is not implemented); blocks mode 'mean' (the tokens' mean into the head), 'atten' (one attention query per disease over the block tokens, each disease's logit from its own pooled vector) or 'flat' (the flattened tokens into a per-disease linear readout)")
    parser.add_argument('--use_pcs', action='store_false',default=True, help='whether to use population structure')
    parser.add_argument('--bi_direct', action='store_true', default=False, help='whether to bi-directional Mamba')
    parser.add_argument('--dropout_rate', type=float, default=0.2, help='Dropout to avoid overfitting')
    parser.add_argument('--fused_add_norm', action='store_false', default=True, help='whether to use residuals')
    parser.add_argument('--n_heads',type=int, default=8, help='number of heads in MHSA')
    parser.add_argument('--n_fcn',type=int, default=2, help='number of hidden layers in FCN')
    parser.add_argument('--l2',type=float, default=1e-5, help='weight decay (L2) in Adam')

    # training define
    parser.add_argument('--gpus', type=int, default=1, help='gpu devices')
    parser.add_argument('--num_workers', type=int, default=1, help='num_workers')
    parser.add_argument('--keep', action='store_false', default=True, help='keep saved model if it exists')
    parser.add_argument('--lr', type=float, default=1e-4, help='learning rate')
    parser.add_argument('--loss_name',  default=None, help='name of loss function')
    parser.add_argument('--max_epoch', type=int, default=100, help='maximum number of epochs')
    parser.add_argument('--batch_size', type=int, default=64, help='batch size of train input data')
    parser.add_argument('--threshold', type=int, default=0.5, help='threshold for transforming probability to binary')  


    # display
    parser.add_argument('--show', action='store_false', default=True, help='display metrics')

    # experiment
    parser.add_argument('--exp_name', default=None, help='name of experiment')
    parser.add_argument('--save_log', default=True, help='save logs for experiment')
    parser.add_argument('--save_results', default=True, help='save results experiment')
    parser.add_argument('--label', default=None, help='target phenotype of experiment')
    parser.add_argument('--dm', default='snps_covs', help='data mode: snps or snps_covs')
    parser.add_argument('--ve', default=None, help='Name of external validation cohort')
    parser.add_argument('--rd_mode', default='ld_all', help='read data mode')
    parser.add_argument('--patience',type=int, default=10, help='patience number in early stopping')
    parser.add_argument('--use_sim', type=str, default='', help='whether to use simulated phenotype')
    parser.add_argument('--use_cov', action='store_false', default=True, help='whether to use covariate data')
    parser.add_argument('--scaling', action='store_false', default=True, help='whether to scale data')
    parser.add_argument('--non_add', action='store_true', default=False, help='whether to use non-additive genes only')
    parser.add_argument('--shuffle', action='store_true', default=False, help='whether to randomly shuffle data')
    parser.add_argument('--cont_pheno', action='store_true', default=False, help='whether the phenotype is continuous')
    # genotype-store datasets only (ignored by the pickle loader)
    parser.add_argument('--snp_stats', default='store', help="SNP scaling statistics: 'store' (computed over all samples at conversion) or 'train' (recomputed on the training split, as the pickle loader does)")
    parser.add_argument('--pos_mode', help="positions for the positional embedding: 'index' or 'pos' (default: what store.json says)")

    # ---- multi-disease training (widedeepgp / main_multilabel.py; main_genome.py ignores these) ----
    parser.add_argument('--labels', help="comma-separated subset of the dataset's label columns (default: all of them)")
    parser.add_argument('--mixer', default='bimamba1', help="sequence block: 'bimamba1' (the published block), 'mamba3', or 'transformer' (a pre-norm encoder layer)")
    # LD-block mode (DeepWideGP-Scripts scripts/widedeepgp-blocks/methods.md): a per-SNP table pooled by LD block, then one mixer over the blocks
    parser.add_argument('--input_mode', default='snps', help="'snps' (the published per-chromosome SNP encoders) or 'blocks' (a per-SNP table pooled by LD block, then one mixer over the block tokens)")
    parser.add_argument('--partition', help="blocks mode: a partition.npz (or its folder) under data/reference/partitions/, or 'uniform:<k>' (k SNPs per block, tests)")
    parser.add_argument('--snp_code', default='dosage', help="blocks mode: 'dosage' (one vector per SNP times its standardised dosage) or 'genotype' (three vectors per SNP, for 0, 1 and 2 copies, interpolated between)")
    parser.add_argument('--embed_dim', type=int, default=16, help='blocks mode: width of the per-SNP table')
    parser.add_argument('--table_kappa', type=float, default=0.03, help="blocks mode: the table's learning rate is kappa * sqrt(batch) / sqrt(SNPs)")
    parser.add_argument('--table_decay', type=float, default=1.0, help="blocks mode: AdamW weight decay of the table (a per-step shrink of every entry)")
    parser.add_argument('--table_eps', type=float, default=2.5e-7, help="blocks mode: Adam epsilon of the table, about eight times the per-entry gradient of a null SNP under the default recipe (batch 64, 40% input masking: measured 3.3e-8 at the top rung), so such entries barely move")
    parser.add_argument('--init_encoder', help='blocks mode: file whose tables start the first layer (masked pretraining by pretrain_blocks.py, or a ridge warm start)')
    parser.add_argument('--freeze_encoder', action='store_true', help='blocks mode: keep the parameters loaded by --init_encoder fixed')
    parser.add_argument('--folds', help="blocks mode: the block ridge's folds.npz; the table then has one copy per fold, a training participant pooled with the copy fitted without them and every other participant with the copy of their pseudo-fold")
    parser.add_argument('--input_mask', type=float, default=0.0, help='blocks mode: share of SNPs set to missing at random on every training step, the rest rescaled (Sigurdsson et al. 2023 used 0.4)')
    parser.add_argument('--sampler', default='rotation', help="'rotation' (each batch balanced on one disease) or 'shuffled'")
    parser.add_argument('--loss_outputs', default='all', help="'all': every output learns from every batch; 'target': only the disease the batch was balanced on")
    parser.add_argument('--gamma', type=float, default=0.5, help='class-weight exponent: 0 none, 0.5 square root, 1 full balance')
    parser.add_argument('--w_max', type=float, default=20.0, help='cap on the class weight of a case')
    parser.add_argument('--no_sampling_correction', action='store_true', help="do not divide each person's loss by their sampling rate")
    parser.add_argument('--head_hidden', type=int, default=256, help='width of the shared hidden layer before the outputs')
    parser.add_argument('--annot', action='store_true', help='use per-SNP annotation vectors (the dataset must provide them)')
    parser.add_argument('--precision', default='32', help="'32' or 'bf16' (bf16 autocast with pooling, head and loss in float32)")
    parser.add_argument('--grad_ckpt', action='store_true', help='activation checkpointing per input sequence')
    parser.add_argument('--accumulate', type=int, default=1, help='batches accumulated per optimiser step')
    parser.add_argument('--val_per_epoch', type=float, default=4.0, help='validation passes per epoch-equivalent')
    parser.add_argument('--max_epoch_equiv', type=float, default=30.0, help='stop after this many epoch-equivalents')
    parser.add_argument('--stop_patience', type=int, default=8, help='validation passes without improvement before stopping (0: never stop early)')
    parser.add_argument('--stop_burnin', type=int, default=0, help='optimiser steps before early stopping may act (Sigurdsson et al. 2023 used 1,000 to 2,000)')
    parser.add_argument('--warmup_steps', type=int, default=0, help='linear learning-rate warm-up, in optimiser steps')
    parser.add_argument('--lr_schedule', default='constant', help="'constant', 'cosine' (to zero over the budget) or 'plateau' (x0.2 after 10 validation passes without improvement; Sigurdsson et al. 2023)")
    parser.add_argument('--seed', type=int, default=33, help='random seed')
    parser.add_argument('--run_dir', default='runs', help='where runs are written')
    parser.add_argument('--experiment', default='default', help='experiment name (a folder of runs)')
    parser.add_argument('--resume', action='store_true', help='continue the run of this name from its last checkpoint, on the same data with the same settings (it may train longer)')
    parser.add_argument('--init_from', help='snapshot whose weights initialise the model (all but the output layer if the labels differ)')
    parser.add_argument('--snapshots_per_decade', type=int, default=8, help='weight snapshots per tenfold increase in steps')
    parser.add_argument('--eval_batch_size', type=int, help='batch size for validation and scoring (default: the training batch size)')
    parser.add_argument('--steps_per_epoch_equiv', type=int, help='override the number of batches in an epoch-equivalent (testing)')
    parser.add_argument('--m3_d_state', type=int, help='Mamba-3 state size (default: 16, the state size of the published block)')
    # linear PRS path and tuning in every run (main_multilabel.py sets its own defaults for these)
    parser.add_argument('--wide', default='off', help="linear PRS path: 'on' (beside the deep network), 'off', 'only' (PRS and covariates without the deep network)")
    parser.add_argument('--prs_var', type=float, default=1.0, help='ridge penalty of the linear PRS path, as the prior variance of each PRS on the logit scale')
    parser.add_argument('--wide_kappa', type=float, default=0.03, help="sets the PRS weights' learning rate: kappa * prs_var * sqrt(batch) / (rbar * sqrt(SNPs))")
    parser.add_argument('--lr_wide', type=float, help='learning rate of the PRS weights (default: from --wide_kappa)')
    parser.add_argument('--wide_freeze', action='store_true', help='keep the PRS weights fixed (with --init_wide_from)')
    parser.add_argument('--init_wide_from', help='checkpoint whose linear PRS path (PRS, covariate weights, intercepts) starts this run')
    parser.add_argument('--prs_grid', help="with --wide only: comma-separated prior variances (as --prs_var) trained side by side in one pass; each disease keeps the value and validation pass with its best tuning AUROC ('none': no grid)")
    parser.add_argument('--tune_trials', type=int, default=0, help='hyper-parameter search of this many trials inside the run (0: train the given settings once)')
    parser.add_argument('--tune_space', default='run', help="what a run's search tunes: 'run' (learning rate, weight decay, dropout and, in blocks mode, the table's pace and decay) or 'table' (the table's pace and decay only)")
    parser.add_argument('--tune_first_given', action='store_true', help='the first trial of a search (network stage) uses the given --lr, --l2 and --dropout, e.g. published settings')
    parser.add_argument('--tune_gpus', help="GPUs for the trials of a search: 'auto' (the free ones minus one), a list such as 1,2,3, or 'none' (one after another in this process)")
    parser.add_argument('--tune_min_validations', type=int, default=2, help='validation passes a trial completes before the pruner may stop it')
    parser.add_argument('--tune_worker', action='store_true', help=argparse.SUPPRESS)
    parser.add_argument('--val_min_participants', type=int, default=0, help='validate at most once per this many participants seen')
    parser.add_argument('--val_max_epoch_equiv', type=float, default=0.0, help='but at least once per this many epoch-equivalents (0: no limit)')
    parser.add_argument('--min_participants', type=int, default=0, help='train for at least this many participants seen (unless stopped early)')
    parser.add_argument('--snapshots_max', type=int, default=0, help='at most this many weight snapshots per run (0: no limit)')

    args = parser.parse_args(argv)
    return args